PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR
VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR
VAR
    prev_Level : INT := 0;
    SafetyTimer : TON;
END_VAR

SafetyTimer(IN := NOT(Level <= 100 AND Level >= 0), PT := T#1s);

IF SafetyTimer.Q THEN
    PumpIn := FALSE;
    ValveOut := FALSE;
END_IF;

IF Level <= 10 THEN
    PumpIn := TRUE;
    ValveOut := FALSE;
ELSIF Level >= 90 THEN
    PumpIn := FALSE;
    ValveOut := TRUE;
ELSE
    PumpIn := FALSE;
    ValveOut := FALSE;
END_IF;

prev_Level := Level;
END_PROGRAM

PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR
VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR
VAR
    prev_Level : INT := 0;
    SafetyTimer : TON;
END_VAR

SafetyTimer(IN := Level >= 90, PT := T#5s);

IF SafetyTimer.Q THEN
    PumpIn := FALSE;
    ValveOut := TRUE;
ELSIF Level <= 10 THEN
    PumpIn := TRUE;
    ValveOut := FALSE;
ELSIF Level >= 90 THEN
    PumpIn := FALSE;
    ValveOut := TRUE;
ELSIF Level >= prev_Level AND Level < 90 THEN
    PumpIn := FALSE;
    ValveOut := FALSE;
ELSIF Level <= prev_Level AND Level > 10 THEN
    PumpIn := TRUE;
    ValveOut := FALSE;
END_IF;

prev_Level := Level;
END_PROGRAM

