END_IF;

END_PROGRAM

PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR
VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR
VAR
    prev_Level : INT := 0;
    prev_PumpIn : BOOL := FALSE;
    prev_ValveOut : BOOL := FALSE;
END_VAR

IF NOT prev_PumpIn AND (Level <= 10 OR Level >= 90) THEN
    PumpIn := TRUE;
ELSIF prev_PumpIn AND (Level > 10 AND Level < 90) THEN
    PumpIn := FALSE;
END_IF;

IF Level >= 90 THEN
    ValveOut := TRUE;
ELSE
    ValveOut := FALSE;
END_IF;

prev_Level := Level;
prev_PumpIn := PumpIn;
prev_ValveOut := ValveOut;

END_PROGRAM

PROGRAM tank_level
VAR_INPUT
    Level : INT;
