    PreviousLevel : INT := 0;
    LowLimit : INT := 10;
    HighLimit : INT := 90;
END_VAR

IF Level >= HighLimit THEN
    PumpIn := FALSE;
    ValveOut := TRUE;
ELSIF Level <= LowLimit THEN
    PumpIn := TRUE;
    ValveOut := FALSE;
ELSE
    PumpIn := PreviousLevel >= HighLimit AND Level < HighLimit;
    ValveOut := FALSE;
END_IF;

PreviousLevel := Level;
END_PROGRAM

