PROGRAM airlock
VAR_INPUT
    OpenA_Cmd : BOOL;
    OpenB_Cmd : BOOL;
END_VAR

VAR_OUTPUT
    DoorA : BOOL;
    DoorB : BOOL;
END_VAR

VAR
    PriorityTimer : TON;
END_VAR

PriorityTimer(IN := OpenA_Cmd AND NOT DoorB OR OpenB_Cmd AND NOT DoorA, PT := T#0s);

DoorA := PriorityTimer.Q AND OpenA_Cmd;
DoorB := PriorityTimer.Q AND OpenB_Cmd;

END_PROGRAM

PROGRAM airlock
VAR_INPUT
    OpenA_Cmd : BOOL;
    OpenB_Cmd : BOOL;
END_VAR

VAR_OUTPUT
    DoorA : BOOL;
    DoorB : BOOL;
END_VAR

VAR
    DoorA_Latched : BOOL := FALSE;
    DoorB_Latched : BOOL := FALSE;
    T_DoorA : TON;
    T_DoorB : TON;
END_VAR

T_DoorA(IN := OpenA_Cmd AND NOT DoorB_Latched, PT := T#0s);
T_DoorB(IN := OpenB_Cmd AND NOT DoorA_Latched, PT := T#0s);

DoorA := T_DoorA.Q OR DoorA_Latched;
DoorB := T_DoorB.Q OR DoorB_Latched;

IF DoorA THEN
    DoorA_Latched := TRUE;
    DoorB_Latched := FALSE;
ELSIF DoorB THEN
    DoorB_Latched := TRUE;
    DoorA_Latched := FALSE;
ELSE
    DoorA_Latched := FALSE;
    DoorB_Latched := FALSE;
END_IF;

END_PROGRAM

