PROGRAM airlock
VAR_INPUT
    OpenA_Cmd : BOOL;
    OpenB_Cmd : BOOL;
END_VAR
VAR_OUTPUT
    DoorA : BOOL;
    DoorB : BOOL;
END_VAR
VAR
    DoorATimer : TON;
    DoorBTimer : TON;
    DoorAPriority : BOOL;
END_VAR

DoorAPriority := NOT DoorB;

IF OpenA_Cmd AND NOT DoorB THEN
    DoorATimer(IN := TRUE, PT := T#0s);
    DoorBTimer(IN := FALSE, PT := T#0s);
    DoorA := DoorATimer.Q;
    DoorB := FALSE;
ELSIF OpenB_Cmd AND NOT DoorA AND DoorAPriority THEN
    DoorATimer(IN := FALSE, PT := T#0s);
    DoorBTimer(IN := TRUE, PT := T#0s);
    DoorA := FALSE;
    DoorB := DoorBTimer.Q;
ELSE
    DoorATimer(IN := FALSE, PT := T#0s);
    DoorBTimer(IN := FALSE, PT := T#0s);
    DoorA := FALSE;
    DoorB := FALSE;
END_IF;

END_PROGRAM

PROGRAM airlock
VAR_INPUT
    OpenA_Cmd : BOOL;
    OpenB_Cmd : BOOL;
END_VAR

VAR_OUTPUT
    DoorA : BOOL;
    DoorB : BOOL;
END_VAR

VAR
    Priority_A : BOOL := FALSE;
    Priority_B : BOOL := FALSE;
    T_DoorA : TON;
    T_DoorB : TON;
END_VAR

T_DoorA(IN := OpenA_Cmd AND NOT DoorB, PT := T#0s);
T_DoorB(IN := OpenB_Cmd AND NOT DoorA, PT := T#0s);

