    Priority_A := TRUE;
    Priority_B := FALSE;
ELSIF NOT OpenA_Cmd AND OpenB_Cmd THEN
    Priority_A := FALSE;
    Priority_B := TRUE;
ELSE
    Priority_A := FALSE;
    Priority_B := FALSE;
END_IF;

END_PROGRAM

