PROGRAM airlock
VAR_INPUT
    OpenA_Cmd : BOOL;
    OpenB_Cmd : BOOL;
END_VAR

VAR_OUTPUT
    DoorA : BOOL;
    DoorB : BOOL;
END_VAR

VAR
    DoorA_Latched : BOOL := FALSE;
    DoorB_Latched : BOOL := FALSE;
    PriorityTimer : TON;
END_VAR

PriorityTimer(IN := OpenA_Cmd AND NOT DoorA_Latched OR OpenB_Cmd AND NOT DoorB_Latched, PT := T#0s);

IF PriorityTimer.Q THEN
    IF OpenA_Cmd AND NOT DoorA_Latched THEN
        DoorA := TRUE;
        DoorB := FALSE;
        DoorA_Latched := TRUE;
        DoorB_Latched := FALSE;
    ELSIF OpenB_Cmd AND NOT DoorB_Latched THEN
        DoorA := FALSE;
        DoorB := TRUE;
        DoorA_Latched := FALSE;
        DoorB_Latched := TRUE;
    ELSE
        DoorA := FALSE;
        DoorB := FALSE;
        DoorA_Latched := FALSE;
        DoorB_Latched := FALSE;
    END_IF;
ELSE
    DoorA := FALSE;
    DoorB := FALSE;
END_IF;

END_PROGRAM

PROGRAM conveyor_ctrl
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    GuardClosed : BOOL;
    Fault : BOOL;
END_VAR
VAR_OUTPUT
    Conveyor : BOOL;
END_VAR
VAR
    Running : BOOL := FALSE;
    SafetyTimer : TON;
END_VAR

SafetyTimer(IN := NOT GuardClosed OR Fault, PT := T#0s);

IF StartPB AND GuardClosed AND NOT Fault THEN
    Running := TRUE;
ELSIF StopPB OR SafetyTimer.Q THEN
    Running := FALSE;
END_IF;

Conveyor := Running;
END_PROGRAM

