PROGRAM batch_reactor
VAR_INPUT
    StartBatch : BOOL;
    Level : INT;
    Temp : INT;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR

VAR
    State : INT := 0;
    LIQ_MIN : INT := 10;
    LVL_HIGH : INT := 80;
    LVL_LOW : INT := 5;
    TEMP_SET : INT := 100;
    PT_REACT : INT := 3;
    FillTimer : TON;
    HeatTimer : TON;
END_VAR

FillTimer(IN := NOT(EStop) AND (State = 1) AND (Level < LVL_HIGH), PT := T#1s);
HeatTimer(IN := NOT(EStop) AND (State = 2) OR (State = 3), PT := T#1s);

CASE State OF
    0: // Idle
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;
        IF StartBatch AND NOT(EStop) THEN
            State := 1;
        END_IF;

    1: // Fill
        FillValve := TRUE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;
        IF FillTimer.Q AND (Level >= LVL_HIGH) THEN
            State := 2;
        END_IF;

    2: // Heat
        FillValve := FALSE;
        Heater := TRUE;
        Agitator := TRUE;
        DrainValve := FALSE;
        IF HeatTimer.Q AND (Temp >= TEMP_SET) THEN
            State := 3;
        END_IF;

    3: // React
        FillValve := FALSE;
        Heater := TRUE;
        Agitator := TRUE;
        DrainValve := FALSE;
        IF NOT(HeatTimer.Q) AND (HeatTimer.I > PT_REACT) THEN
            State := 4;
        END_IF;

    4: // Drain
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := TRUE;
        IF NOT(DrainValve) AND (Level <= LVL_LOW) THEN
            State := 0;
        END_IF;
END_CASE;

END_PROGRAM

PROGRAM batch_reactor
VAR_INPUT
    StartBatch : BOOL;
    Level : INT;
    Temp : INT;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR

VAR
    State : INT := 0;
    LIQ_MIN : INT := 10;
    LVL_HIGH : INT := 80;
    LVL_LOW : INT := 5;
    TEMP_SET : INT := 100;
    PT_REACT : TIME := T#3s;
    FillTimer : TON;
    DrainTimer : TON;
END_VAR

IF NOT EStop THEN
    State := 0;
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
ELSIF StartBatch AND Level >= LIQ_MIN THEN
    CASE State OF
        0:
            IF Level < LVL_HIGH THEN
                State := 1;
                FillTimer(IN := TRUE, PT := T#1s);
            ELSE
                State := 2;
            END_IF;
        1:
            IF FillTimer.Q THEN
                FillValve := TRUE;
                State := 2;
            END_IF;
        2:
            IF Temp >= TEMP_SET THEN
                State := 3;
            END_IF;
        3:
            IF NOT DrainTimer.Q THEN
                Heater := TRUE;
                Agitator := TRUE;
                DrainTimer(IN := TRUE, PT := PT_REACT);
            ELSE
                State := 4;
            END_IF;
        4:
            IF Level <= LVL_LOW THEN
                State := 0;
                FillValve := FALSE;
                Heater := FALSE;
                Agitator := FALSE;
                DrainValve := FALSE;
            END_IF;
    END_CASE;
END_IF;

FillValve := FillValve AND NOT DrainValve;
DrainValve := DrainValve AND NOT FillValve;
Heater := Heater AND (State >= 2);
Agitator := Agitator AND (State >= 2);

END_PROGRAM

