T_Fill(IN := NOT EStop AND StartBatch AND Level < LVL_HIGH AND Level >= LIQ_MIN, PT := T#1s);
T_React(IN := NOT EStop AND State = 3, PT := PT_REACT);

CASE State OF
    0: // Idle
        FillValve := FALSE;
