    PT_REACT : INT := 3;
    T_Fill : TON;
    T_React : TON;
END_VAR

T_Fill(IN := NOT(EStop) AND StartBatch AND Level >= LIQ_MIN AND State = 0, PT := T#0s);
T_React(IN := NOT(EStop) AND State = 2, PT := T#(PT_REACT * T#1s));

CASE State OF
    0: // Idle
        IF T_Fill.Q THEN
            State := 1;
        END_IF;

    1: // Fill
        FillValve := TRUE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;

        IF Level >= LVL_HIGH OR NOT(T_Fill.Q) THEN
            State := 2;
        END_IF;

    2: // Heat
        FillValve := FALSE;
        Heater := TRUE;
        Agitator := TRUE;
        DrainValve := FALSE;

        IF Temp >= TEMP_SET OR NOT(NOT(EStop)) THEN
            State := 3;
        END_IF;

    3: // React
        FillValve := FALSE;
        Heater := TRUE;
        Agitator := TRUE;
        DrainValve := FALSE;

        IF T_React.Q OR NOT(NOT(EStop)) THEN
            State := 4;
        END_IF;

    4: // Drain
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := TRUE;

        IF Level <= LVL_LOW OR NOT(T_Drain.Q) THEN
            State := 0;
        END_IF;
END_CASE;

