    HeatTimer : TON;
END_VAR

IF NOT EStop THEN
    State := 0;
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;

ELSIF StartBatch AND Level >= LIQ_MIN THEN
    CASE State OF
        0:
            IF Level < LVL_HIGH THEN
                State := 1;
                FillTimer(IN := TRUE, PT := T#0s);
            END_IF;

        1:
            IF FillTimer.Q THEN
                State := 2;
                FillValve := FALSE;
                HeatTimer(IN := TRUE, PT := T#0s);
            END_IF;

        2:
            IF Temp >= TEMP_SET THEN
                State := 3;
                HeatTimer(IN := TRUE, PT := T#0s);
            END_IF;

        3:
            IF HeatTimer.T#PT_REACT THEN
                State := 4;
                DrainValve := FALSE;
                HeatTimer(IN := TRUE, PT := T#0s);
            END_IF;

        4:
            IF Level <= LVL_LOW THEN
                State := 0;
                FillValve := FALSE;
                Heater := FALSE;
                Agitator := FALSE;
                DrainValve := FALSE;
            END_IF;
    END_CASE;
END_IF;

IF State = 1 OR State = 4 THEN
    DrainValve := FALSE;
END_IF;

IF State = 2 OR State = 3 THEN
    FillValve := FALSE;
END_IF;

IF State = 2 OR State = 3 THEN
    Heater := TRUE;
    Agitator := TRUE;
END_IF;

IF State = 0 OR State = 1 OR State = 4 THEN
    Heater := FALSE;
    Agitator := FALSE;
END_IF;
