            IF PedReq THEN
                State := 1;
                T_Green(IN := FALSE);
            END_IF;
        ELSE
            T_Green(IN := TRUE, PT := PT_GREEN);
        END_IF;

    1:
        CarGreen := FALSE;
        CarYellow := TRUE;
        CarRed := FALSE;
        PedWalk := FALSE;

        IF T_Yellow.Q THEN
            State := 2;
            T_Yellow(IN := FALSE);
        ELSE
            T_Yellow(IN := TRUE, PT := PT_YELLOW);
        END_IF;

    2:
        CarGreen := FALSE;
        CarYellow := FALSE;
        CarRed := TRUE;
        PedWalk := TRUE;

        IF T_Walk.Q THEN
            State := 0;
            T_Walk(IN := FALSE);
        ELSE
            T_Walk(IN := TRUE, PT := PT_WALK);
        END_IF;
END_CASE;

