    State : INT := 0;
    PurgeTimer : TON;
    IgnitionTimer : TON;
END_VAR

CASE State OF
    0:
        IF StartPB AND NOT EStop THEN
            State := 1;
            PurgeTimer(IN := TRUE, PT := T#3s);
        END_IF;

    1:
        IF PurgeTimer.Q THEN
            State := 2;
            IgnitionTimer(IN := TRUE, PT := T#2s);
        END_IF;

    2:
        Fan := TRUE;
        Fuel := TRUE;
        Ignition := TRUE;
        IF IgnitionTimer.Q AND Flame THEN
            State := 3;
        ELSE
            State := 0;
        END_IF;

    3:
        Fan := TRUE;
        Fuel := TRUE;
        Ignition := FALSE;
        IF NOT Flame OR StopPB OR NOT EStop THEN
            State := 0;
        END_IF;
END_CASE;

Fan := FALSE;
Fuel := FALSE;
Ignition := FALSE;

IF State = 1 OR State = 2 THEN
    Fan := TRUE;
END_IF;

IF State = 2 OR State = 3 THEN
    Fuel := TRUE;
END_IF;

IF State = 2 THEN
    Ignition := TRUE;
END_IF;

