VAR
    Lead : INT := 0;
    PrevDemand : BOOL := FALSE;
    LeadChangeTimer : TON;
END_VAR

LeadChangeTimer(IN := NOT PrevDemand AND Demand, PT := T#0s);

PrevDemand := Demand;

IF NOT EStop THEN
    Pump1 := FALSE;
    Pump2 := FALSE;
ELSE
    IF Lead = 0 THEN
        IF Demand THEN
            Pump1 := TRUE;
            Pump2 := FALSE;
        ELSIF NOT Demand AND LeadChangeTimer.Q THEN
            Lead := 1;
            Pump1 := FALSE;
            Pump2 := TRUE;
        END_IF;
    ELSE
        IF Demand THEN
            Pump1 := FALSE;
            Pump2 := TRUE;
        ELSIF NOT Demand AND LeadChangeTimer.Q THEN
            Lead := 0;
            Pump1 := TRUE;
            Pump2 := FALSE;
        END_IF;
    END_IF;
END_IF;

