PROGRAM gate
VAR_INPUT
    OpenCmd : BOOL;
    CloseCmd : BOOL;
    OpenLimit : BOOL;
    CloseLimit : BOOL;
    Obstruction : BOOL;
END_VAR

VAR_OUTPUT
    MotorOpen : BOOL;
    MotorClose : BOOL;
END_VAR

VAR
    State : INT := 0;
    OpeningTimer : TON;
    ClosingTimer : TON;
END_VAR

OpeningTimer(IN := OpenCmd AND NOT OpenLimit AND NOT MotorClose AND NOT Obstruction, PT := T#1s);
ClosingTimer(IN := CloseCmd AND NOT CloseLimit AND NOT MotorOpen AND NOT Obstruction, PT := T#1s);

CASE State OF
    0:  // Idle
        MotorOpen := FALSE;
        MotorClose := FALSE;
        IF OpenCmd AND NOT OpenLimit THEN
            State := 1;
        ELSIF CloseCmd AND NOT (CloseLimit OR Obstruction) THEN
            State := 2;
        END_IF;

    1:  // Opening
        MotorOpen := TRUE;
        MotorClose := FALSE;
        IF OpenLimit OR Obstruction THEN
            MotorOpen := FALSE;
            State := 0;
        END_IF;

    2:  // Closing
        MotorOpen := FALSE;
        MotorClose := TRUE;
        IF CloseLimit OR Obstruction THEN
            MotorClose := FALSE;
            State := 0;
        END_IF;
END_CASE;

END_PROGRAM

