VAR
    State : INT := 0;
    OpeningTimer : TON;
    ClosingTimer : TON;
END_VAR

CASE State OF
    0: // Idle
        IF OpenCmd AND NOT OpenLimit THEN
            State := 1;
            OpeningTimer(IN := TRUE, PT := T#0s);
        ELSIF CloseCmd AND NOT (CloseLimit OR Obstruction) THEN
            State := 2;
            ClosingTimer(IN := TRUE, PT := T#0s);
        END_IF;

    1: // Opening
        MotorOpen := TRUE;
        MotorClose := FALSE;
        IF OpenLimit OR Obstruction THEN
            State := 0;
            OpeningTimer(IN := FALSE);
        END_IF;

    2: // Closing
        MotorOpen := FALSE;
        MotorClose := TRUE;
        IF CloseLimit OR Obstruction THEN
            State := 0;
            ClosingTimer(IN := FALSE);
        END_IF;
END_CASE;

END_PROGRAM

